// fwui.h — lives in wiliOGbsp as a library. C11. Declare screens, never place pixels.

typedef struct fwui_screen fwui_screen;
typedef struct fwui_gfx fwui_gfx;              // thin wrapper over the BSP graphics LCD API

typedef enum {                                  // the ONLY events an app ever sees —
  FWUI_EV_SELECT,   // GREEN on a row/page (arg = index)
  FWUI_EV_CHANGE,   // ValueEditor value moved (arg = value)
  FWUI_EV_ACTION,   // long-GREEN, the one app slot
  FWUI_EV_TICK,     // periodic redraw tick for canvas screens (arg = ms)
  FWUI_EV_ENTER, FWUI_EV_LEAVE
} fwui_event;       // GRAY/RED/nav never reach the app; the framework consumes them.

typedef void (*fwui_handler)(fwui_screen *s, fwui_event ev, int arg);

void fwui_init(const char *app_name);           // status bar, legend, power policy, GRAY overlay
fwui_screen *fwui_list  (const char *title, const char *const *items, int n, fwui_handler h);
fwui_screen *fwui_pager (const char *title, int n_pages, void (*draw_page)(fwui_gfx*,int), fwui_handler h);
fwui_screen *fwui_value (const char *title, const char *unit, int min, int max, int step,
                         int *value, fwui_handler h);
fwui_screen *fwui_text  (const char *title, const char *body, fwui_handler h);
fwui_screen *fwui_canvas(const char *title, void (*draw)(fwui_gfx*), fwui_handler h);
void fwui_set_action (fwui_screen *s, const char *label);   // labels long-GREEN in the legend
void fwui_menu_add   (const char *label, void (*fn)(void)); // extra item in the GRAY overlay
void fwui_push(fwui_screen *s);   // RED pops automatically; popping the root exits to App Explorer
void fwui_pop (void);
bool fwui_confirm(const char *msg);             // blocking modal: GREEN=true, RED=false
void fwui_toast  (const char *msg);
void fwui_leds_progress(uint8_t pct, uint32_t rgb);  // FeedbackKit: 7-LED strip mirror
void fwui_run(void);                            // event loop: buttons, redraw, power — never returns

// ---- worked example: 3-screen pomodoro (menu -> duration -> running timer) ----
static int duration_min = 25;

static void timer_ev(fwui_screen *s, fwui_event ev, int arg) {
  if (ev == FWUI_EV_ACTION) pomo_toggle_pause();          // long-GREEN, legend says "Pause"
  if (ev == FWUI_EV_TICK)   fwui_leds_progress(pomo_pct(), 0xFF4000);
}
static void draw_timer(fwui_gfx *g) { fwui_gfx_bigstat(g, pomo_mmss()); }

static void menu_ev(fwui_screen *s, fwui_event ev, int arg) {
  if (ev != FWUI_EV_SELECT) return;
  if (arg == 0) {                                          // "Start"
    fwui_screen *t = fwui_canvas("Focus", draw_timer, timer_ev);
    fwui_set_action(t, "Pause");
    fwui_push(t);                                          // RED = quit timer, back to menu
  } else if (arg == 1) {                                   // "Duration"
    fwui_push(fwui_value("Duration", "min", 5, 90, 5, &duration_min, NULL));
  }                                                        // GREEN commits, RED cancels — free
}

int main(void) {
  fwui_init("wilidoro");
  static const char *items[] = { "Start", "Duration" };
  fwui_push(fwui_list("wilidoro", items, 2, menu_ev));     // root: RED here exits the app
  fwui_run();
}

// fwui.h — lives in the BSP; app = declare screens, framework does the rest
