// --- 3-screen pomodoro-ish feature, complete ---
static int mins = 25;
static uint8_t pct;
static void running(void *u){ fwui_screen_t *s = fwui_screen("Running");
  fwui_add_label(s, "%d min focus", mins);
  fwui_add_progress(s, &pct, true);
  fwui_add_action(s, "Abort timer", abort_cb, NULL);      // shows in LONG-GREEN menu
  fwui_push(s); }
static void settings(void *u){ fwui_screen_t *s = fwui_screen("Settings");
  fwui_add_spinner(s, "Minutes", 5, 60, 5, &mins);
  fwui_push(s); }                                          // LONG-YELLOW returns to Home
static const char *home_items[] = {"Start", "Settings"};
static void home_sel(size_t i, void *u){ i ? settings(u) : running(u); }
int main(void){ fwui_init(NULL);
  fwui_screen_t *h = fwui_screen("Pomodoro");
  fwui_add_menu(h, home_items, 2, home_sel, NULL);
  fwui_push(h); fwui_run(); }

/* fwog_ui.h — lives in the BSP next to fwog_display.h. C11. */

typedef struct {
    const char *label;                 /* <=5 chars; NULL slot = dim dot   */
    void (*on_press)(void *ctx);
    const char *long_label;            /* NULL = no long binding           */
    void (*on_long)(void *ctx);
    bool repeat;                       /* 8 Hz auto-repeat of on_press     */
} fwog_ui_key_t;

typedef struct {
    const char   *title;                       /* status bar + breadcrumb  */
    fwog_ui_key_t keys[FWOG_BTN_COUNT];        /* GRAY slot is IGNORED:    */
                                               /* framework owns Back/Home */
    void (*draw)(fwog_gfx_t *g, void *ctx);    /* paint 320x192 content    */
    void (*on_tick)(uint32_t now_ms, void *ctx); /* optional, 20 Hz        */
    void *ctx;
} fwog_ui_screen_t;

void fwog_ui_init(const char *app_name);       /* rail+status up, grammar armed */
void fwog_ui_push(const fwog_ui_screen_t *s);  /* enter screen, rail redrawn    */
void fwog_ui_pop(void);                        /* what GRAY does for you        */
void fwog_ui_dirty(void);                      /* request content redraw        */
void fwog_ui_run(void);                        /* loop; returns on Home/exit    */

/* Stock components (each pushes a screen): */
void fwog_ui_list(const char *title, const char *const *items, size_t n,
                  void (*on_select)(size_t idx, void *ctx), void *ctx);
bool fwog_ui_confirm(const char *msg);                       /* GREEN/RED  */
int  fwog_ui_spin(const char *title, int lo, int hi, int step, int initial);
void fwog_ui_toast(const char *msg);

/* ---- A 3-screen feature: menu -> brightness editor -> about text ---- */
static void about_draw(fwog_gfx_t *g, void *ctx) {
    fwog_gfx_text(g, 0, 0, "Orca Notes v2", 3);
}
static const fwog_ui_screen_t about = { .title = "About", .draw = about_draw };

static void menu_pick(size_t idx, void *ctx) {
    if (idx == 0) {                            /* screen 2: value editor  */
        int b = fwog_ui_spin("Brightness", 0, 100, 5, cfg.bright);
        if (b >= 0) { cfg.bright = b; fwog_ui_toast("Saved"); }
    } else {
        fwog_ui_push(&about);                  /* screen 3: static page   */
    }
}
int main(void) {
    fwog_ui_init("Orca Notes");
    static const char *items[] = { "Brightness", "About" };
    fwog_ui_list("Settings", items, 2, menu_pick, NULL);   /* screen 1    */
    fwog_ui_run();                             /* GRAY pops, gray-hold exits */
}

/* wiliui.h — declarative screens over lcd_text/st7789. Lives in bsp/display_cpu/ui/. */

typedef struct { const char *text; uint16_t chip_rgb565; /* 0 = no color chip */ } ui_row_t;

typedef struct ui_screen {
    const char *title;                     /* breadcrumb + status bar */
    enum { UI_LIST, UI_TEXT, UI_VALUE, UI_HERO } kind;
    /* UI_LIST */
    const ui_row_t *rows; uint8_t nrows;
    void (*on_select)(uint8_t row);        /* GREEN */
    /* UI_TEXT */
    const char *body;
    /* UI_VALUE */
    int vmin, vmax, vstep; int *value;     /* GRAY/BLUE edit w/ repeat */
    void (*on_commit)(int v);              /* GREEN */
    /* UI_HERO */
    void (*render)(void);                  /* draws 320x200 content region only */
    /* optional app verb — label is force-rendered in the hint bar */
    const char *yellow_label;      void (*on_yellow)(void);
    const char *yellow_long_label; void (*on_yellow_long)(void);
    uint32_t tick_ms; void (*on_tick)(void);   /* 0 = no timer */
} ui_screen_t;

void ui_init(const char *app_name);            /* chrome up, nav stack empty */
void ui_push(const ui_screen_t *s);            /* enter screen (stack, depth 8) */
void ui_pop(void);                             /* what RED does; app rarely calls it */
void ui_dirty(void);                           /* redraw current screen's dirty rows */
void ui_toast(const char *msg);
bool ui_confirm(const char *question);         /* modal GREEN/RED */
void ui_led_progress(uint8_t num, uint8_t den);/* 7-LED ring override */
void ui_on_exit(void (*save_state)(void));     /* runs before return to App Explorer */
void ui_run(void);                             /* event loop; returns when user exits */

/* --- entire 3-screen feature: menu -> brightness editor -> about --- */
static int bright = 5;
static const ui_screen_t about = { .title="About", .kind=UI_TEXT, .body="wilidoro v2\n..." };
static const ui_screen_t edit  = { .title="Brightness", .kind=UI_VALUE,
    .vmin=0,.vmax=10,.vstep=1,.value=&bright,.on_commit=apply_brightness };
static const ui_row_t items[] = {{"Brightness",0},{"About",0}};
static void pick(uint8_t i){ ui_push(i==0 ? &edit : &about); }
static const ui_screen_t home = { .title="Settings", .kind=UI_LIST,
    .rows=items,.nrows=2,.on_select=pick,
    .yellow_label="Reset",.on_yellow=factory_reset };
int main(void){ ui_init("Settings"); ui_push(&home); ui_run(); }

